(* [comment removed for export] *)
Lemma pbs (m : nat) : forall (j a : Z) (fxq : FPState) Rq Mq mdq crq kq,
  utf8_valid l = true -> Z.of_nat m = n - 1 - j -> 0 <= j -> a = 1 + pl_size n + j ->
  inv Mq mdq crq kq a ->
  getr Rq (PMK.reg 1) = Z_to_bv 64 0x363b8 -> getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - 48) ->
  getr Rq (PMK.reg 8) = Z_to_bv 64 (fb + 440) -> getr Rq (PMK.reg 9) = Z_to_bv 64 (n - j) -> getr Rq (PMK.reg 18) = Z_to_bv 64 (dptr + j) ->
  getr Rq (PMK.reg 10) = Z_to_bv 64 (fb + 496) -> getr Rq (PMK.reg 11) = Z_to_bv 64 (sp - 33) -> csl Rq ->
